<?php
require_once __DIR__ . '/db.php';require_once __DIR__ . '/smtp.php';api_method('POST');$in=api_input();if(!$in&&$_POST)$in=$_POST;$name=trim(strip_tags((string)($in['name']??'')));$email=trim((string)($in['email']??''));$subject=trim(strip_tags((string)($in['subject']??'')));$message=trim((string)($in['message']??''));if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$subject===''||$message==='')api_json(422,['ok'=>false,'error'=>'Please complete all contact fields with a valid email']);$pdo=db();$q=$pdo->prepare('INSERT INTO contacts(name,email,subject,message,created_at) VALUES(?,?,?,?,?)');$q->execute([$name,$email,$subject,$message,gmdate('c')]);$to=app_env('MAIL_TO');$mailSubject='New contact: '.$subject;$body="Name: $name\nEmail: $email\nSubject: $subject\n\n$message";$mailed=$to!==''&&smtp_send($to,$mailSubject,$body);if(!$mailed&&$to!=='')$mailed=@mail($to,$mailSubject,$body,'From: '.app_env('SMTP_FROM',$to));api_json(200,['ok'=>true,'mailed'=>$mailed]);
